        const target = event.target;

        // Verificamos si el elemento que disparó el evento es una celda de datos editable.
        if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
            let rawValueTarget = target.textContent;

            // 1. Procesar la celda editada (target) primero, ya que su valor ha cambiado.
            if (rawValueTarget && typeof rawValueTarget === 'string' && rawValueTarget.trim().startsWith('=')) {
                try {
                    const calculatedValue = evaluateFormula(rawValueTarget);
                    // Actualizamos el texto de la celda con el resultado numérico, no la fórmula.
