            editableCells.forEach(cell => {
                let rawValue = cell.textContent;

                // Solo recalcular si la celda contiene una fórmula y no es la que acabamos de editar (aunque recalcularla no haría daño, es más eficiente saltársela).
                if ((rawValue && typeof rawValue === 'string' && rawValue.trim().startsWith('=')) && cell !== target) {
