function loadDataFromLocalStorage() {
    const savedData = JSON.parse(localStorage.getItem('spreadsheetData')) || {};

    document.querySelectorAll('#spreadsheet-body td[contenteditable="true"]').forEach(cell => {
        const col = cell.getAttribute('data-col');
        const row = cell.getAttribute('data-row');
        const key = `${col}${row}`;

        if (savedData[key] !== undefined) {
            // Restaurar el contenido de la celda con el valor guardado.
            cell.textContent = savedData[key]; 
        }
    });
}

/**
 * Guarda el contenido actual de una celda en localStorage.
 * @param {string} col Columna (A, B, etc.)
 * @param {string} row Fila (1, 2, etc.)
 * @param {string} value El valor a guardar.
 */
function saveDataToLocalStorage(col, row, value) {
    const savedData = JSON.parse(localStorage.getItem('spreadsheetData')) || {};
    const key = `${col}${row}`;
    savedData[key] = value;
    localStorage.setItem('spreadsheetData', JSON.stringify(savedData));
}

