function setupCellEditing() {
    const spreadsheetBody = document.getElementById('spreadsheet-body');

    if (!spreadsheetBody) {
        console.error("Error: No se encontró el cuerpo de la hoja de cálculo con id 'spreadsheet-body'.");
        return;
    }

    // Helper function to recalculate a single cell and update storage/DOM
    const calculateAndDisplayCell = (cell, col, row) => {
        let rawFormula = localStorage.getItem(`${col}${row}`);
        let formulaString = null;
        let currentValue = null;

        if (typeof rawFormula === 'string') {
            try {
                // Attempt to parse stored data as JSON first
                const storedData = JSON.parse(rawFormula);
                formulaString = storedData.formula || '';
                currentValue = storedData.value;
            } catch (e) {
                // If parsing fails, assume it's a simple value string/number
                formulaString = rawFormula;
                currentValue = rawFormula;
            }
        }

        let finalValueToDisplay = currentValue;

        if (formulaString && formulaString.trim().startsWith('=')) {
            try {
                const calculatedValue = evaluateFormula(formulaString);
                finalValueToDisplay = calculatedValue; 
                // Update the cell content to show the result, not the formula
                cell.textContent = finalValueToDisplay; 

                // Save structured data: formula and value
                localStorage.setItem(`${col}${row}`, JSON.stringify({
                    formula: formulaString,
                    value: calculatedValue
                }));

            } catch (e) {
                console.error(`Error al calcular la fórmula en ${col}${row}:`, e);
                // If calculation fails, display the original content/formula and save it as is.
                cell.textContent = formulaString; 
                localStorage.setItem(`${col}${row}`, JSON.stringify({
                    formula: formulaString,
                    value: formulaString // Save error state or raw input
                }));
            }
        } else {
             // If not a formula, just ensure the display matches the stored value/input
             cell.textContent = finalValueToDisplay; 
             localStorage.setItem(`${col}${row}`, JSON.stringify({
                 formula: null,
                 value: finalValueToDisplay
             }));
        }
    };


    // Usamos event delegation para escuchar cambios en cualquier <td> dentro del tbody.
    spreadsheetBody.addEventListener('input', function(event) {
        const target = event.target;

        if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
            const col = target.getAttribute('data-col');
            const row = target.getAttribute('data-row');
            let rawValue = target.textContent;
            let finalValueToDisplay = rawValue;

            // 1. Procesar el valor del celda que disparó el evento (target)
            if (rawValue && typeof rawValue === 'string' && rawValue.trim().startsWith('=')) {
                try {
                    const calculatedValue = evaluateFormula(rawValue);
                    finalValueToDisplay = calculatedValue; 
                    target.textContent = finalValueToDisplay; 

                } catch (e) {
                    console.error("Error al calcular la fórmula:", e);
                    // Si falla el cálculo, mantenemos el valor original para que el usuario lo vea.
                }
            } else {
                 // Si es solo texto o número, simplemente dejamos el contenido como está.
            }

            // 2. Guardar el contenido final en localStorage (actualizando la estructura de datos)
            localStorage.setItem(`${col}${row}`, JSON.stringify({
                formula: rawValue.trim().startsWith('=') ? rawValue : null,
                value: finalValueToDisplay
            }));


            // 3. RECALCULAR TODAS LAS FÓRMULAS DE LA HOJA (Dependency Update)
            const rows = spreadsheetBody.querySelectorAll('tr');
            rows.forEach(rowElement => {
                const cells = rowElement.querySelectorAll('td[contenteditable="true"]');
                cells.forEach(cell => {
                    const cellCol = cell.getAttribute('data-col');
                    const cellRow = cell.getAttribute('data-row');

                    // Solo recalcular si la celda contiene una fórmula (verificando el storage)
                    if (localStorage.getItem(`${cellCol}${cellRow}`) && JSON.parse(localStorage.getItem(`${cellCol}${cellRow}`)).formula) {
                        calculateAndDisplayCell(cell, cellCol, cellRow);
                    }
                });
            });
        }
    });

    // Opcional: Manejar el evento de foco para asegurar que la experiencia sea fluida al hacer clic.
