    if (!spreadsheetBody) {
        console.error("Error: No se encontró el cuerpo de la hoja de cálculo con id 'spreadsheet-body'.");
        return;
    }

    // Helper function to recalculate a single cell and update storage/DOM
    const calculateAndDisplayCell = (cell, col, row) => {
        let rawFormula = localStorage.getItem(`${col}${row}`);
        let formulaString = null;
        let currentValue = null;

        if (!rawFormula) return; // No data stored

        try {
            // Attempt to parse stored data as JSON first
            const storedData = JSON.parse(rawFormula);
            formulaString = storedData.formula || '';
            currentValue = storedData.value;
        } catch (e) {
            // If parsing fails, assume it's a simple value string/number
            formulaString = rawFormula;
            currentValue = rawFormula;
        }

        let finalValueToDisplay = currentValue;

        if (formulaString && formulaString.trim().startsWith('=')) {
            try {
                const calculatedValue = evaluateFormula(formulaString);
                finalValueToDisplay = calculatedValue; 
                // Update the cell content to show the result, not the formula
                cell.textContent = finalValueToDisplay; 

                // Save structured data: formula and value
                localStorage.setItem(`${col}${row}`, JSON.stringify({
                    formula: formulaString,
                    value: calculatedValue
                }));

            } catch (e) {
                console.error(`Error al calcular la fórmula en ${col}${row}:`, e);
                // If calculation fails, display the original content/formula and save it as is.
                cell.textContent = formulaString; 
                localStorage.setItem(`${col}${row}`, JSON.stringify({
                    formula: formulaString,
                    value: formulaString // Save error state or raw input
                }));
            }
        } else {
             // If not a formula, just ensure the display matches the stored value/input
             cell.textContent = finalValueToDisplay; 
             localStorage.setItem(`${col}${row}`, JSON.stringify({
                 formula: null,
                 value: finalValueToDisplay
             }));
        }
    };


    // Usamos event delegation para escuchar cambios en cualquier <td> dentro del tbody.
