            // 2. Guardar el contenido final en localStorage (actualizando la estructura de datos)
            localStorage.setItem(`${col}${row}`, JSON.stringify({
                formula: rawValue.trim().startsWith('=') ? rawValue : null,
                value: finalValueToDisplay
            }));


            // 3. RECALCULAR TODAS LAS FÓRMULAS DE LA HOJA (Dependency Update)
            const rows = spreadsheetBody.querySelectorAll('tr');
            rows.forEach(rowElement => {
                const cells = rowElement.querySelectorAll('td[contenteditable="true"]');
                cells.forEach(cell => {
                    const cellCol = cell.getAttribute('data-col');
                    const cellRow = cell.getAttribute('data-row');

                    // Solo recalcular si la celda contiene una fórmula (verificando el storage)
                    if (localStorage.getItem(`${cellCol}${cellRow}`) && JSON.parse(localStorage.getItem(`${cellCol}${cellRow}`)).formula) {
                        calculateAndDisplayCell(cell, cellCol, cellRow);
                    }
                });
            });
        }
    });

    // Opcional: Manejar el evento de foco para asegurar que la experiencia sea fluida al hacer clic.
